async function failed(s: CenaState, reason: string, d: CenaDeps): Promise<void> {
  if (s.phase === 'video' && s.videoAttempt < CENA_VIDEO_ATTEMPTS) {
    s.videoAttempt++; s.jobs = s.jobs.filter(j => j.kind === 'image');
